mq0 = [
{"q":"根据《“健康中国2030”规划纲要》，以下哪些目标正确？","o":["居民健康素养水平要提高到30%","重大慢性疾病过早死亡率要比2015年降低30%","人均预期寿命提高到79岁","人均预期寿命提高到100岁"],"a":[0,1,2],"e":"随着《“健康中国2030”规划纲要》的推进，居民健康素养水平要提高到30%，重大慢性疾病过早死亡率要比2015年降低30%，人均预期寿命提高到79岁。"},
{"q":"关于作者写作本书的特点，正确的有？","o":["不是讲食品营养，而是一本临床营养实践方面的经验分享","针对慢病患者、亚健康人群的营养问题","分享真实的典型病例，从常见误区及常见疾病入手","书里给出了适用于所有人的具体食谱"],"a":[0,1,2],"e":"第一，这本书不是讲食品营养，也不属于大众营养，而是一本临床营养实践方面的经验分享，针对的是慢病患者、亚健康人群的营养问题。第二，分享真实的典型病例……第三，书里没有具体的食谱。"},
{"q":"作者夏萌的从医经历包括？","o":["1983年从医学院毕业后进入天坛医院神经内科工作","后来调到安贞医院","2009年毛遂自荐成为营养科医生，组建临床营养科","一直只从事营养配餐工作，从未做过临床"],"a":[0,1,2],"e":"1983年从医学院毕业后，我进入天坛医院神经内科工作。13年后，因为路途太远加上体力不支，我调到了离家较近的安贞医院……2009年，卫生部下发文件要求，全国三甲医院必须成立临床营养科……我毛遂自荐，成为一名营养科医生。"},
{"q":"作者自己患病期间的经历包括？","o":["2000年冬天感冒后出现血尿","肾穿病理结果显示35个肾小球有7个是硬化的","服用ACEI类降压药后出现嗓子痒、干咳不止","服用他汀类降脂药后完全没有任何不适"],"a":[0,1,2],"e":"在一次感冒持续半个月之后，我发现自己血尿了……我做了肾穿，病理结果显示：35个肾小球有7个是硬化的……肾内科大夫建议我吃ACEI类降压药，结果吃了才知道，这种药会带来嗓子痒、干咳不止的不良反应；为了降血脂，我又开始服用他汀类降脂药，最终浑身肌肉疼痛不已的副作用让我不得不停药。"},
{"q":"作者通过3个月的营养调整，身体出现了哪些变化？","o":["尿蛋白消失了","潜血变成了1个+","后来潜血也消失了","血压、血脂立刻全部恢复正常"],"a":[0,1,2],"e":"万万没想到，经过3个月的营养调整，尿蛋白消失了！潜血变成了1个+！又过了一段时间，潜血也消失了。"},
{"q":"作者撤掉降压药、血压血脂血糖恢复正常、脂肪肝消失，是在什么阶段之后？","o":["持续学习营养学半年后开始觉悟","把营养知识应用得得心应手","身体越来越好，不再请病假","手术切除脂肪肝之后"],"a":[0,1,2],"e":"半年后，我慢慢地觉悟了，有种破茧成蝶的感觉……我对营养知识的应用变得得心应手，身体也越来越好，从此不再请病假，门诊、病房所有的工作量我都能与别人一样完成。不仅如此，我撤掉了降压药，血压、血脂、血糖完全恢复正常，脂肪肝也消失了。"},
{"q":"作者在门诊中观察到，高血压患者最爱的食物多是什么？","o":["面条","咸菜","清淡的蔬菜","水果"],"a":[0,1],"e":"高血压患者大多最爱的食物有两种：面条和咸菜。当我让他们把面条和咸菜都戒掉之后，血压开始明显下降。"},
{"q":"在糖尿病患者身上，作者常发现他们？","o":["太喜欢喝粥","太喜欢吃米和面","满脑子都是“没有主食就不叫吃饭”","特别爱吃肥肉"],"a":[0,1,2],"e":"在很多糖尿病患者身上，我发现他们太喜欢喝粥、吃米和面了，满脑子都是“没有主食就不叫吃饭”。我让患者把粥戒掉，教患者吃饭怎样吃得杂、吃得健康。"},
{"q":"关于那位51岁主动脉夹层患者的会诊，正确的有？","o":["他吃素，从来不吸烟、不饮酒，每天都运动","长年缺乏蛋白质导致大血管变得很脆弱，手术前已经营养不良","作者在会诊单上写明静脉里给什么、鼻饲里给什么","他因为长期吸烟导致营养不良"],"a":[0,1,2],"e":"一问患者家属，他夫人告诉我：他吃素，从来不吸烟，不饮酒，每天都运动。我明白了，他由于长年缺乏蛋白质导致大血管变得很脆弱，手术前已经营养不良，经过大手术的打击，体内营养储备已被全部掏空。于是，我立即在会诊单上写了静脉里给什么，鼻饲里给什么。"},
{"q":"那位51岁患者接受营养支持治疗后的恢复过程是？","o":["3天后血压不用升压药也能稳定住","再调整方案3天后开始有尿","两周之后已经可以坐在病床上吃饭，四周之后出院","出院后一直无法恢复工作"],"a":[0,1,2],"e":"按照这样的方式治疗了3天后，主治医生告诉我，血压不用升压药也能稳定住了……按照新方案治疗了3天，患者开始有尿……两周之后，患者已经可以坐在病床上吃饭。四周之后，患者出院。出院后，患者家属一直向我咨询怎样调养身体，根据我给出的方案，6个月后，患者已经可以上班。"},
{"q":"关于重症抢救中的营养支持，正确的有？","o":["营养支持已经成为最基本的治疗手段","经济发达国家医院里的ICU工作人员中必定有营养科医生","临床营养学能发挥的作用超出大众一般认为的食品营养和大众营养范畴","营养支持只在患者出院后才需要"],"a":[0,1,2],"e":"其实在重症抢救方面，营养支持已经成为最基本的治疗手段。经济发达国家医院里的ICU工作人员中必定有营养科医生……临床营养学能够发挥的作用完全超出大众一般认为的食品营养和大众营养范畴。"},
{"q":"那位46岁血糖高的患者，作者的饮食建议包括？","o":["把晚饭的面条换成一根老玉米","平时多吃些瘦肉","每天必须喝牛奶","主食尽量多吃面条"],"a":[0,1,2],"e":"我让他把晚饭的面条换成一根老玉米，平时多吃些瘦肉，每天必须喝牛奶。"},
{"q":"关于面条这种食物，作者的评价是？","o":["吸收得太快，很容易升血糖","很容易饿","除了痛快痛快嘴，百害而无一利","是最适合糖尿病患者的晚餐主食"],"a":[0,1,2],"e":"面条这种食物，吸收得太快，很容易升血糖，也很容易饿。他选了这种食物做晚餐，除了痛快痛快嘴，百害而无一利。"},
{"q":"为什么混合性食物中有肉类会更好？","o":["会降低餐后血糖的上升速度","同时提供了结构所需的蛋白质等营养素","只提供能量而不提供结构物质","会使血糖迅速飙升"],"a":[0,1],"e":"当然可以吃，混合性食物中如果有肉类，会降低餐后血糖的上升速度。"},
{"q":"关于“慢病”，正确的有？","o":["是慢慢养成的病，康复起来也需要慢慢调整","能够康复的患者不过是把人人能听懂的道理落到实处","做到了大多数人做不到的坚持","只要吃对一种灵丹妙药就能迅速痊愈"],"a":[0,1,2],"e":"所谓慢病，就是慢慢养成的病，康复起来也需要慢慢调整，这些能够康复的患者不过是把人人都能听懂的道理落到实处，做到了大多数人做不到的坚持。"},
{"q":"按照“寿命等于成熟期的5～7倍者为长寿”的说法，人类应该能活到多少岁？","o":["100岁","175岁","100～175岁","80多岁"],"a":[0,1,2],"e":"国际上有个标准，寿命等于成熟期的5～7倍者为长寿。按照这个说法，长寿之人应该能活到100～175岁。"},
{"q":"《世界卫生统计报告（2015）》中的人均寿命数据，正确的有？","o":["中国女性77岁，男性74岁","日本国民平均寿命84岁，全世界排名第一","美国女性81岁，男性76岁","中国人均寿命已经超过日本"],"a":[0,1,2],"e":"中国在此次报告中的人均寿命为：女性77岁，男性74岁。咱们的邻居日本，人均寿命在全世界排名第一，国民平均寿命为84岁……该报告上显示美国女性的平均寿命为81岁，男性为76岁，依然超过了我们。"},
{"q":"关于细胞的生命周期，正确的有？","o":["血管的内皮细胞1天就会死亡","胃黏膜细胞3～5天更替一次","肺表面的细胞寿命是2～3周","大脑细胞大约每20年更新一次"],"a":[0,1,2],"e":"比如血管的内皮细胞1天就会死亡；胃黏膜细胞3～5天更替一次；肺表面的细胞寿命是2～3周；皮肤最外面的角质层细胞28天左右就要换新；肝细胞能存活150天左右；心脏细胞更新速度要慢很多，大约需要20年；而大脑细胞一生一世不再更新。"},
{"q":"关于人体细胞更新的描述，正确的有？","o":["皮肤最外面的角质层细胞28天左右就要换新","肝细胞能存活150天左右","心脏细胞更新大约需要20年","大脑细胞更新最快，约7天一次"],"a":[0,1,2],"e":"皮肤最外面的角质层细胞28天左右就要换新；肝细胞能存活150天左右；心脏细胞更新速度要慢很多，大约需要20年；而大脑细胞一生一世不再更新。"},
{"q":"属于“慢病”的疾病有？","o":["冠心病、高血压、糖尿病","肿瘤、抑郁症","气管炎、哮喘、慢性肾病","车祸造成的骨折"],"a":[0,1,2],"e":"我们最常见的冠心病、高血压、糖尿病、肿瘤、抑郁症、气管炎、哮喘、慢性肾病等疾病，都是由不恰当的生活方式引起的，医学工作者将这些疾病统一归类为慢性非传染性疾病，简称“慢病”。"},
{"q":"关于慢病的统计数据，正确的有？","o":["中国每5人中就有1人确诊为慢病患者","慢病导致的死亡人数占中国总死亡人数的85%","慢病的医疗花费大，死亡率、残疾率高","慢病导致的死亡和残疾人数少于车祸和战争"],"a":[0,1,2],"e":"治疗慢病的医疗花费大，死亡率、残疾率高，比车祸、战争造成的死亡和残疾人数还要多得多。据统计，中国每5人中就有1人确诊为慢病患者，慢病导致的死亡人数占中国总死亡人数的85%。"},
{"q":"为什么对抗疗法不适用于慢病？","o":["对抗疗法以前是用来针对外来因素给人体造成的疾病","慢病是行为方式错误造成的，矫正错误行为才是根本","慢病源于各种不平衡的长期累加","慢病和生活方式没有关系"],"a":[0,1,2],"e":"治疗方向错了——这种对抗疗法以前是用来针对外来因素给人体造成的疾病……慢病是行为方式错误造成的，矫正错误行为才是根本。"},
{"q":"属于身体向我们发出的亚健康求救信号的有？","o":["易疲劳、疼痛、过敏","咳嗽、便秘、腹泻","血压增高、血糖上升","身高突然变高"],"a":[0,1,2],"e":"此时会出现一些我们常说的亚健康状态，正是身体向我们发出的求救信号，如易疲劳、疼痛、过敏、咳嗽、便秘、腹泻、血压增高、血糖上升……"},
{"q":"在细胞损伤与修复的“天平”中，属于左边砝码（损伤和消耗）的有？","o":["睡眠","运动","吸烟、饮酒","饮食"],"a":[0,1,2],"e":"就如同一个天平，左边有五个砝码——睡眠、运动、吸烟、饮酒、心态，右边只有一个砝码——饮食，左边的错误累加都会要求右边砝码加重。"},
{"q":"人体细胞的自我修复能力取决于？","o":["与生俱来的细胞生命周期（先天因素），决定修复速度","后天的营养状况（后天因素），决定修复质量","每天的喝水量","居住地的气候"],"a":[0,1],"e":"人体细胞的自我修复能力取决于两个主要因素，一个是与生俱来的细胞生命周期，另一个是后天的营养状况，即先天因素和后天因素。先天因素（细胞固有的更新周期）决定了修复速度，后天因素（营养状态）决定了修复质量。"},
{"q":"以下哪些情况属于“细胞损伤程度已到无可挽回”的严重损伤？","o":["肾功能衰竭","已经心肌梗死的组织","脑血栓之后坏死的脑组织","普通感冒引起的暂时乏力"],"a":[0,1,2],"e":"当然这里有一个前提，就是细胞损伤程度还不到无可挽回的情况下。有些严重损伤是无法再修复的，比如肾功能衰竭、已经心肌梗死的组织、脑血栓之后坏死的脑组织等。"},
{"q":"七大营养素包括？","o":["碳水化合物、蛋白质、脂类","维生素、矿物质","膳食纤维、水","酒精和咖啡因"],"a":[0,1,2],"e":"这些营养，从临床医学角度准确地描述，叫作七大营养素，包括：碳水化合物……蛋白质……脂类……维生素……矿物质……膳食纤维……水。"},
{"q":"关于脂类的分类，正确的有？","o":["分为脂肪和类脂","脂肪又叫甘油三酯，分为必需脂肪酸和非必需脂肪酸","类脂包括磷脂、胆固醇、胆固醇脂、糖脂","类脂占脂类的绝大部分"],"a":[0,1,2],"e":"脂类（分为脂肪和类脂，脂肪又叫甘油三酯，分为必需脂肪酸和非必需脂肪酸；类脂包括磷脂、胆固醇、胆固醇脂、糖脂）。脂类中包括脂肪和类脂，其中类脂只占5%。"},
{"q":"基础代谢是指？","o":["一个人躺着不动、室温保持在20～25℃时测出来的能量消耗","一般男性为1400千卡／天左右","一般女性在1300千卡／天左右","运动时消耗的能量"],"a":[0,1,2],"e":"一个人如果躺着不动，室温保持在20～25℃，测出来的能量消耗称为基础代谢。一般来讲，男性为1400千卡／天左右，女性在1300千卡／天左右。"},
{"q":"用脑越多，越需要多补充哪些营养素？","o":["蛋白质、维生素、矿物质","脂类中的胆固醇、磷脂","DHA和EPA","酒精"],"a":[0,1,2],"e":"第二，心理方面。大脑消耗的营养素与肌肉消耗的营养素不一样，用脑越多越需要多补充蛋白质、维生素、矿物质，还有脂类中的胆固醇、磷脂和大家都很关注的DHA和EPA。"},
{"q":"熬夜会额外消耗哪些营养素？","o":["维生素A","维生素B族","磷脂和蛋白质","膳食纤维"],"a":[0,1,2],"e":"第三，熬夜。消耗的营养素会更多，如维生素A、维生素B族、磷脂和蛋白质等。"},
{"q":"关于吸烟与喝酒对营养素的影响，正确的有？","o":["吸烟需要更多的抗氧化剂来对抗尼古丁等毒素的伤害","喝酒伤肝，需要更多营养素来修复肝脏细胞","喝酒需要补充维生素B族和蛋白质","喝酒有益于肝脏细胞的修复"],"a":[0,1,2],"e":"第四，吸烟。需要更多的抗氧化剂来对抗尼古丁等毒素对人体的伤害。第五，喝酒。伤肝，需要更多的营养素来修复肝脏细胞，如维生素B族和蛋白质。"},
{"q":"关于每天吃盐不超过6克的说法，作者的观点是？","o":["这个标准不能一概而论","在南方潮湿闷热的地区，尤其是夏天，就不能要求一定要低于6克","北方人以及整天在空调房间里工作不出汗的人一定要减少盐的摄入","无论什么地区都必须严格执行6克标准"],"a":[0,1,2],"e":"比如，我们现在都提倡低盐，要求每天吃盐不要超过6克。但是，在南方潮湿闷热的地区，尤其是夏天，就不能要求一定要低于6克了……但是北方人以及整天在空调房间里工作不出汗的人就一定要减少盐的摄入。"},
{"q":"福建地区急诊室出现较多低钠血症老年患者的原因包括？","o":["当地潮湿闷热，人们本来就出汗多","许多老年人不习惯家里开空调，还每天出去运动","随汗液流失的钠盐多，又讲究吃少盐清淡的食物","当地食物中普遍不含有钠"],"a":[0,1,2],"e":"就是因为福建地区潮湿闷热，人们本来就出汗多，再加上许多老年人不习惯家里开空调，而且每天出去运动，随汗液流失的钠盐就多。老年人又讲究要吃少盐清淡的食物，如果不注意及时补充钠盐，人们很容易在大汗后出现低钠血症。"},
{"q":"关于细胞膜的成分，正确的有？","o":["磷脂所占的比例较高，占50%～70%","胆固醇占30%左右","蛋白质占20%左右","糖类物质占膜重的50%以上"],"a":[0,1,2],"e":"如果我们把一个人身上所有细胞的膜收集起来进行检测，我们会发现里面实际上主要是三种成分：蛋白质、磷脂、胆固醇。磷脂所占的比例较高，占50%～70%，胆固醇占30%左右，蛋白质占20%左右。还有一点糖类物质，如糖蛋白或糖脂，占膜重的2%～10%。"},
{"q":"关于线粒体产生能量，正确的有？","o":["线粒体一般情况下燃烧的是葡萄糖","当葡萄糖不足时燃烧脂肪","蛋白质不能直接被燃烧，要在肝脏中转化成葡萄糖以后才能成为能量","蛋白质可以直接在线粒体中被燃烧供能"],"a":[0,1,2],"e":"所有的细胞工作都需要能量，负责产生能量的线粒体很像工厂的大锅炉，这个大锅炉里一般情况下燃烧的是葡萄糖（碳水化合物中的一种）。当葡萄糖不足时燃烧脂肪，蛋白质不能直接被燃烧，要在肝脏中转化成葡萄糖以后才能成为能量。"},
{"q":"七大营养素为细胞新陈代谢提供的支持包括？","o":["为细胞新陈代谢提供能量","为新生细胞更新提供结构原料","为新陈代谢提供媒介","直接替代DNA的遗传功能"],"a":[0,1,2],"e":"第一，为细胞新陈代谢提供能量。第二，为新生细胞更新提供结构原料。第三，为新陈代谢提供媒介。第四，养肠道细菌。"},
{"q":"关于酶和辅酶，正确的有？","o":["酶的主体部分是蛋白质","辅酶的主要成分是维生素和矿物质","新陈代谢速度越快，需要的酶越多","辅酶的主体部分是脂类"],"a":[0,1,2],"e":"人的新陈代谢是在酶的催化下完成的。新陈代谢速度越快，需要的酶越多。酶是从哪里来的呢？是食物中的营养转化的。酶的主体部分是蛋白质，辅助部分叫作辅酶，辅酶的主要成分是维生素和矿物质。"},
{"q":"关于激素的分类，正确的有？","o":["甲状腺素、胰岛素属于蛋白质类激素","肾上腺素属于胆固醇类激素","吃鸡蛋、内脏、肉类可提供形成激素的前体","激素全部属于蛋白质类"],"a":[0,1,2],"e":"内分泌系统是调节细胞代谢的重要角色，而激素分为蛋白质类激素和胆固醇类激素，比如甲状腺素、胰岛素都属于蛋白质类激素，肾上腺素就属于胆固醇类激素。所以说一个人吃动物性食品，比如鸡蛋、内脏、肉类，里面有蛋白质和胆固醇，这些正好是形成激素的前体。"},
{"q":"关于人体内的细菌，正确的有？","o":["人体由40万亿～60万亿个细胞组成","人身上的细菌数量是人体细胞数量的10倍","细菌主要在肠道里","肠道里的细菌靠食物中的蛋白质养活"],"a":[0,1,2],"e":"人体由40万亿～60万亿个细胞组成，而我们身上的细菌数量是人体细胞数量的10倍，并且主要在肠道里，肠道里的细菌靠食物中的膳食纤维养活。"},
{"q":"食物进到人体中有哪几个主要去向？","o":["给细胞提供能量","成为细胞结构","调节细胞代谢、养肠道菌群","直接变成人体的遗传物质"],"a":[0,1,2],"e":"总结起来，食物进到人体中有四个主要去向：给细胞提供能量、成为细胞结构、调节细胞代谢、养肠道菌群。"},
{"q":"以下对应关系正确的有？","o":["给细胞提供能量——主要靠碳水化合物类","成为细胞结构——主要靠蛋白质类和脂类","调节细胞代谢——蛋白质类和胆固醇类，还有维生素、矿物质","养肠道菌群——主要靠蛋白质"],"a":[0,1,2],"e":"给细胞提供能量——主要靠碳水化合物类，也就是粮食、水果等。成为细胞结构——主要靠蛋白质类和脂类，主要存在于肉、蛋、奶、鱼中。调节细胞代谢——蛋白质类和胆固醇类，还有维生素、矿物质。养肠道菌群——食物中的膳食纤维。"},
{"q":"关于基因与生活方式的关系，作者的观点是？","o":["基因决定了人应该睡多长时间、应该吃多少食物以及运动的时间和程度","顺应基因确定好的细胞需求去生活，就能长寿","生活方式与基因编码不对等，疾病就会找上门来","基因完全不能影响人的饮食需求"],"a":[0,1,2],"e":"基因决定了心脏怎样跳、肝脏做什么功、肾脏干什么活，决定了人应该睡多长时间、应该几点起床几点睡觉、应该喝多少水、应该吃多少食物以及运动的时间和程度。当人们顺应基因确定好的细胞需求去生活，就能长寿；如果一味地任性，想吃什么就吃什么，想几点睡就几点睡，生活方式与基因编码不对等，疾病就会找上门来。"},
{"q":"关于旧石器时代的饮食变化，正确的有？","o":["大约距今250万年开始，古猿下地寻找食物，开始了荤素搭配的饮食结构","大约80多万年前，部分人种把火种引进山洞，开始吃熟肉","把动物煮熟或烤熟后吃，蛋白质和脂类更容易消化吸收","此时人类已经学会种植大麦和小麦"],"a":[0,1,2],"e":"从大约距今250万年开始，非洲东部地壳发生变化，完全靠采集植物为生的古猿只好下地寻找食物，就此开始了荤素搭配的饮食结构……大约80多万年前，有部分人种发现野火烧过的动物肉既好吃，又好消化，于是把火种引进了山洞……把打来的动物煮熟或者烤熟了吃，摄入的蛋白质和脂类更容易消化吸收，大脑获得了更多滋养。"},
{"q":"远古人类在外形上的重要特点包括？","o":["脑容量显著增大","下巴逐渐收缩进去","牙齿变小","身高迅速降低"],"a":[0,1,2],"e":"这时的人类在外形上有一些非常重要的特点：脑容量显著增大（由于大脑获得了更多的营养素，从而促进了大脑的快速发育），下巴逐渐收缩进去，牙齿也变小了（由于食物煮熟后容易咀嚼和消化）。"},
{"q":"关于农牧时代（农业革命），正确的有？","o":["人类开始种植大麦、小麦、豆类、蔬菜和水果等农作物","不再四处迁徙，不再居无定所","从营养素的获取来讲，农业革命的开始实际上是食物营养下降的开始","食谱变得更宽，动物类食品比例增加"],"a":[0,1,2],"e":"人们种植大麦、小麦、豆类、蔬菜和水果等农作物，不再为驯化猪、牛、羊、马、骆驼等动物四处迁徙，不再居无定所……但是从营养素的获取来讲，农业革命的开始实际上是食物营养下降的开始……由于植物类食物的增加……动物类食品开始减少。"},
{"q":"农业革命给人类带来的变化包括？","o":["食谱变窄","粮食、蔬菜、水果从种植到收获到储存都变得越来越容易","人们不再需要在自然界追逐猎物和主动采集，体质逐渐衰退","人类大脑增容和体质增强持续加速"],"a":[0,1,2],"e":"人类不再需要与大型动物搏杀，每天吃的食物是主动种植的植物或者饲养的动物，食谱变窄了……再加上人们不再需要像一万年前那样在自然界追逐猎物和主动采集各种食物，而是去附近交换或购买，体质逐渐衰退……定居生活带来的是人类大脑增容和体质增强的戛然而止。"},
{"q":"工业革命后出现的新食物包括？","o":["各种添加剂：口味剂、防腐剂、保鲜剂、色素等","工业生产的反式脂肪酸（人造黄油、起酥油）","精米、精面及其衍生出的点心、面条、米粉","天然采摘的野菜和野果"],"a":[0,1,2],"e":"一些从未在我们生活中出现的食物出现了，比如：各种添加剂：口味剂、防腐剂、保鲜剂、色素等。工业生产的反式脂肪酸（人造黄油、起酥油）。精米、精面……精米、精面衍生出的各种食物，比如各种点心、面条、米粉等。"},
{"q":"工业革命对食物营养素的影响包括？","o":["几乎所有食物中的营养素都在贬值","据日本2006年调查，和20年前相比菠菜的营养素只剩下了不到20%","新鲜食物反而变得稀少","食物中的营养素含量大幅提高"],"a":[0,1,2],"e":"这一切带来的后果是，几乎所有食物中的营养素都在贬值。据日本2006年发布的一则调查显示，和20年前相比，菠菜的营养素只剩下了不到20%……冰箱、食品添加剂和特殊的食品加工方法，解决了食物储存中的困难，新鲜食物反而变得稀少。"},
{"q":"关于人类食物种类的变化，正确的有？","o":["老祖宗可以从自然界摄取7000多种食物","随着农牧业开展及工业加工食品出现，人们常吃的食物只有500多种","有6000多种老祖宗吃的食物都从餐桌上消失了","现代人常吃的食物种类比老祖宗更多"],"a":[0,1,2],"e":"我们的老祖宗可以从自然界摄取7000多种食物……但是，随着农牧业的开展以及工业加工食品的出现，人们常吃的食物只有500多种。也就是说，有6000多种我们老祖宗吃的食物都从我们的餐桌上消失了。"},
{"q":"关于2万～1万年前（旧石器时代向新石器时代转化时期）的完美饮食结构，正确的有？","o":["植物性食物占65%左右，主要是水果、蔬菜、坚果、豆类和蜂蜜","动物性食物占35%左右，主要是肉类、蛋类、鱼和虾贝类","这种结构带来低钠高钾、高纤维素、高蛋白质以及ω-3脂肪酸高含量","动物性食物占65%左右"],"a":[0,1,2],"e":"植物性食物占65%左右，主要是水果、蔬菜、坚果、豆类和蜂蜜。动物性食物占35%左右，主要是肉类、蛋类、鱼和虾贝类。这样完美的饮食结构带来了大量的维生素和矿物质，低钠高钾、高纤维素、高蛋白质以及脂肪酸中ω-3脂肪酸的高含量。"},
{"q":"针对现代人，作者提出的饮食原则包括？","o":["尽量摄入天然食物，动物类、植物类食物每天都要吃，减少加工食品摄入","动物类食物最好占一天食物的35%","植物类食物占一天食物的65%，种类尽量多样化","粮食类食物以精米、精面为主"],"a":[0,1,2],"e":"第二，尽量摄入天然食物，动物类、植物类食物每天都要吃，注意减少加工食品摄入量。第三，动物类食物（肉、蛋、奶、鱼等）最好占一天食物的35%……植物类食物包括蔬菜、水果和粮食，占一天食物的65%……最不好的是精米、精面，因为精米、精面是工业化的产物。"},
{"q":"关于“一盘土豆炖牛肉”与“白菜炖粉条＋土豆炖牛肉＋红薯＋凉拌山药”的对比，正确的有？","o":["第二种搭配看上去有6种食物，其实主要含有同一种营养素——碳水化合物","粉条、土豆、红薯和山药主要含有同一种营养素","食物丰富并不能等同于营养素丰富","第二种搭配的营养素种类明显多于第一种"],"a":[0,1,2],"e":"第二种搭配看上去有6种食物，好像很丰富了，其实粉条、土豆、红薯和山药主要含有同一种营养素——碳水化合物。4个菜用营养素一评估，其实只有3种，并不比第一种搭配好多少。所以食物丰富并不能等同于营养素丰富，这是两件事，需要我们科学地对待。"},
{"q":"那个10岁女孩不长个儿，她的日常饮食特点是？","o":["早餐一个馒头，一碗白米粥","中午和晚上都是一碗米饭加上1～2种蔬菜","1个月吃一两个鸡蛋，不吃肉，不吃鱼，不喝牛奶","每天喝牛奶并吃大量肉类"],"a":[0,1,2],"e":"一了解，孩子每天的饮食如下：早餐一个馒头，一碗白米粥；中午和晚上都是一碗米饭加上1～2种蔬菜。1个月吃一两个鸡蛋，不吃肉，不吃鱼，不喝牛奶。"},
{"q":"那个10岁女孩不长个儿的原因包括？","o":["馒头、粥和米饭都是碳水化合物，只提供能量","蔬菜提供维生素，提供蛋白质的鸡蛋几乎没有","脂类完全缺席","碳水化合物吃得不够多"],"a":[0,1,2],"e":"从营养素角度看，馒头、粥和米饭都是碳水化合物，蔬菜提供维生素，提供蛋白质的鸡蛋几乎没有，而脂类是完全缺席的。"},
{"q":"关于结构物质与能量物质，正确的有？","o":["结构物质主要指磷脂、蛋白质、胆固醇","粮食的主要成分是碳水化合物，提供的是能量","吃得太多碳水化合物只会转化成脂肪，变不成细胞的结构","碳水化合物可以直接变成细胞膜"],"a":[0,1,2],"e":"结构物质主要指磷脂、蛋白质、胆固醇。如果这些结构性营养缺失了，细胞无法按照DNA的指令完成增生和修复，身体发育就会受到限制。粮食的主要成分是碳水化合物，提供的是能量，是葡萄糖，吃得太多只会转化成脂肪，变不成细胞的结构。"},
{"q":"关于蛋白质、脂肪和碳水化合物之间的转化，正确的有？","o":["碳水化合物能转化成脂肪，脂肪也能转化成碳水化合物","蛋白质可以转化成碳水化合物","碳水化合物和脂肪在体内只能转化为非必需氨基酸","碳水化合物和脂肪可以直接转化为必需氨基酸"],"a":[0,1,2],"e":"碳水化合物能转化成脂肪，脂肪也能转化成碳水化合物。蛋白质可以转化成碳水化合物。但不是所有的蛋白质都能由碳水化合物和脂肪直接转化而来。蛋白质是由氨基酸构成的，而碳水化合物和脂肪在体内只能转化为非必需氨基酸，必需氨基酸是必须要从外界摄取的。"},
{"q":"那位伤口长不上的患者，作者解释的正确内容包括？","o":["主食是碳水化合物，会转化为脂肪存在肚子上，所以肚子大","皮肤、肌肉、骨头等部位的细胞主要成分是磷脂、蛋白质和胆固醇","应多吃肉类、鸡蛋、酸奶和猪肝，伤口才能快点儿长好","多吃主食就能让伤口快速愈合"],"a":[0,1,2],"e":"“您平时特爱吃主食，对吧？主食是碳水化合物，吃到身体中会转化为脂肪存在肚子上，所以您的肚子大。但是皮肤、肌肉、骨头等部位的细胞主要成分是磷脂、蛋白质和胆固醇，您吃的食物没有这些营养，细胞就长不出来……这种情况下，多吃肉类、鸡蛋、酸奶和猪肝，伤口才能快点儿长好。”"},
{"q":"关于吃进去的胆固醇与肝脏造的胆固醇，作者的解释是？","o":["吃进去的胆固醇会成为人体细胞结构的一部分","肝脏造的胆固醇才与动脉粥样硬化有关","两者不是一回事儿","吃进去的胆固醇会直接造成动脉粥样硬化"],"a":[0,1,2],"e":"吃进去的胆固醇会成为人体细胞结构的一部分，肝脏造的胆固醇才与动脉粥样硬化有关，不是一回事儿。"},
{"q":"关于同样多的鸡肉和鸡汤，作者的观点是？","o":["鸡肉更有营养","心脏手术后要限制进入身体的液体量","心脏手术后要保证磷脂、蛋白质、胆固醇和各种维生素的摄入","鸡汤比鸡肉更有营养"],"a":[0,1,2],"e":"同样多的鸡肉和鸡汤，哪个更有营养？当然是鸡肉。而且心脏手术后不能喝这么多汤汤水水，要限制进入身体的液体量，又要保证磷脂、蛋白质、胆固醇和各种维生素的摄入，所以，每一口饭都非常重要。"},
{"q":"关于营养素在细胞中的吸收和释放顺序，正确的有？","o":["食物中的碳水化合物、蛋白质和脂肪一同摄入时，最先被利用的一定是碳水化合物","碳水化合物冲在最前面，进入细胞的线粒体，直接变为能量","蛋白质和脂肪变成细胞膜的结构或者成为某些有生物活性的物质","脂肪永远最先被消耗"],"a":[0,1,2],"e":"营养素在细胞中的吸收和释放都是需要排队的。食物中的碳水化合物、蛋白质和脂肪如果一同被摄入，最先被利用的一定是碳水化合物，它冲在最前面，进入细胞的线粒体，直接变为能量。蛋白质和脂肪变成细胞膜的结构或者成为某些有生物活性的物质，如酶。"},
{"q":"关于饥饿时的分解比例，正确的有？","o":["以脂肪分解为主，占80%左右","蛋白质的分解约占20%","脂肪和蛋白质的分解比例约为4∶1","以蛋白质分解为主，占80%左右"],"a":[0,1,2],"e":"一般来讲，人在饥饿时，以脂肪分解为主，占80%左右，蛋白质的分解约占20%，脂肪和蛋白质的分解比例约为4∶1。"},
{"q":"那位健身小伙子半年下来不长肌肉、全身无力的原因包括？","o":["碳水化合物摄入不足造成体内蛋白质和脂肪分解","早晨只吃鸡蛋，能量只能从鸡蛋中来","鸡蛋里的蛋白质没有成为肌肉细胞的成分，而是变成能量被燃烧掉了","他吃了太多碳水化合物"],"a":[0,1,2],"e":"很明显，因为碳水化合物摄入不足造成了他体内蛋白质和脂肪分解……第二天早上应该摄入一些碳水化合物，结果他早晨仅仅只吃鸡蛋，于是上午的能量只能从鸡蛋中来。能量不够用，因此鸡蛋里的蛋白质没有成为肌肉细胞的成分，而是变成能量给燃烧掉了。"},
{"q":"关于碳水化合物的摄入，作者强调？","o":["不能因为碳水化合物无法转化成蛋白质而轻视碳水化合物的摄入","不要随意减少主食","要掌握好三种营养素的比例","为了长肌肉应尽量不吃主食"],"a":[0,1,2],"e":"所以，并不能因为碳水化合物无法转化成蛋白质而轻视碳水化合物的摄入，随意减少主食，要掌握好三种营养素的比例。"},
{"q":"食物摄入不均衡可能造成的后果包括？","o":["碳水化合物摄入太多又消耗不掉，会造成肥胖、糖尿病等疾病","为细胞提供结构和形成调节物质的营养素不足，会导致阿尔茨海默病、呆小症等","该消耗的消耗不掉，形成负担","营养素不足会自动由蛋白质转化补齐，没有任何影响"],"a":[0,1,2],"e":"食物摄入不均衡，如果碳水化合物摄入太多，人体消耗不掉，就会造成肥胖、糖尿病等疾病；而为细胞提供结构和形成调节物质的营养素不足，会导致阿尔茨海默病、呆小症等。该消耗的消耗不掉，形成负担；该形成结构的不足以形成结构；该形成激素等调节物质的营养素也不足，最终造成人体功能缺失，这就是我们常说的“病从口入”。"},
{"q":"关于能量密度和营养密度，正确的有？","o":["能量密度指单位体积中所含的提供给细胞的能量营养素有多少","营养密度指单位体积中所含的营养素有多少","对运动量不大的现代人来说，最好的食物选择是低能量密度、高营养密度","体力劳动者更应选择低能量密度、低营养密度的食物"],"a":[0,1,2],"e":"对运动量不大的现代人来说，最好的食物选择是：低能量密度，高营养密度。如果是体力劳动者，那就要高能量密度，高营养密度。"},
{"q":"属于“空能量食物”的有？","o":["白米粥","甜饮料","白面馒头和大米饭","鸡蛋"],"a":[0,1,2],"e":"一碗米饭里基本上就只有碳水化合物和少量植物蛋白，缺乏大多数营养素。我们把这种只有能量而没有其他营养素的食物叫作空能量食物，比如白米粥、甜饮料、白面馒头和大米饭。"},
{"q":"关于地中海膳食结构，正确的有？","o":["最符合低能量、高营养这一标准的膳食结构","多年的临床研究证明，这是预防高血压、高血脂、糖尿病等现代慢病最有效的饮食方式","澳大利亚一项历时10年的研究表明，最常吃传统地中海式食品的人死于心血管病的风险要低30%","它会明显增加心血管病的死亡率"],"a":[0,1,2],"e":"最符合低能量、高营养这一标准的膳食结构，就是地中海膳食结构。多年的临床研究也证明，这是预防高血压、高血脂、糖尿病等现代慢病最有效的饮食方式。澳大利亚研究人员一项历时10年的研究表明，传统地中海式饮食的确可以避免患心脏病……死于心血管病的风险要低30%。"},
{"q":"关于地中海式饮食与糖尿病风险的研究，正确的有？","o":["希腊的研究显示地中海式饮食还可能降低患糖尿病的风险","分析显示富含鱼类、坚果、蔬菜和水果的地中海式饮食可使人们患糖尿病的风险减少21%","对患有心脏病的高危人群，可使患糖尿病的风险减少27%","地中海式饮食只对欧洲人有效"],"a":[0,1,2],"e":"一个来自希腊的研究显示，地中海式饮食还可能降低患糖尿病的风险……分析显示，与其他饮食相比，富含鱼类、坚果、蔬菜和水果的地中海式饮食，可以使人们患糖尿病的风险减少21%。对于患有心脏病的高危人群，地中海式饮食可以使人们患糖尿病的风险减少27%……综合结果表明，地中海式饮食对欧洲人和非洲人同样可以降低糖尿病风险。"},
{"q":"关于地中海式饮食的其他研究结论，正确的有？","o":["可以减缓老年痴呆症病情的恶化，可使痴呆患者的死亡风险减少73%","可以保护大脑免受血管损伤，降低发生中风和记忆力减退的风险","可以减少30%的乳腺癌发病率","会显著增加乳腺癌的发病率"],"a":[0,1,2],"e":"美国后来又连续几年做了这方面的对比研究，发现地中海式饮食可以减缓老年痴呆症病情的恶化，可使痴呆患者的死亡风险减少73%。《神经病学文献》发表的一项研究报告称，地中海式饮食可以保护大脑免受血管损伤，降低发生中风和记忆力减退的风险。另外，许多研究还显示地中海式饮食可以起到预防乳腺癌的作用，可以减少30%的乳腺癌发病率。"},
{"q":"作者认为评估一个人是否健康，为什么先看能量？","o":["能量比七大营养素更宏观","能量更易辨识","当一个人能量不平衡时，再进一步深挖究竟是哪种营养素不平衡","能量平衡可以完全代表七大营养素平衡"],"a":[0,1,2],"e":"为什么呢？我们看一个人是否健康，最简单的就是先评估能量，因为它比七大营养素更宏观，更易辨识。当一个人能量不平衡时，我们再进一步深挖，去分析究竟是哪种营养素不平衡。"},
]
